    (1, 'essence-mascara-lash-princess', 'Essence Mascara Lash Princess', 'beauty', 'The Essence Mascara Lash Princess is a popular mascara known for its volumizing and lengthening effects. Achieve dramatic lashes with this long-lasting and cruelty-free formula.', 999, 10.48, 2.56, 99, 'In Stock', 'Essence', 'BEA-ESS-ESS-001', 4, 15.14, 13.08, 22.99, '1 week warranty', 'Ships in 3-5 business days', 'No return policy', 48, 'https://cdn.dummyjson.com/product-images/beauty/essence-mascara-lash-princess/thumbnail.webp', array['beauty', 'mascara']),
