    (4, 'red-lipstick', 'Red Lipstick', 'beauty', 'The Red Lipstick is a classic and bold choice for adding a pop of color to your lips. With a creamy and pigmented formula, it provides a vibrant and long-lasting finish.', 1299, 12.16, 4.36, 91, 'In Stock', 'Chic Cosmetics', 'BEA-CHI-LIP-004', 1, 18.11, 28.38, 22.17, '3 year warranty', 'Ships in 1 week', '7 days return policy', 40, 'https://cdn.dummyjson.com/product-images/beauty/red-lipstick/thumbnail.webp', array['beauty', 'lipstick']),
